INSERT INTO content_sections (company_id, source_id, category, title, summary, full_content, display_order, page_reference, section_reference, tags)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'company','Executive Summary','A ClickPet digitaliza pet shops independentes com uma infraestrutura B2B2C pronta para operação.','O ClickPet é uma plataforma B2B2C desenvolvida para digitalizar pet shops independentes, oferecendo infraestrutura completa para vendas online, gestão de pedidos e conexão direta com consumidores. A empresa está em estágio Pré-Seed, com MVP concluído, aplicativo publicado, plataforma operacional e primeiros estabelecimentos utilizando a solução.',1,NULL,'executive_summary',ARRAY['empresa','resumo','investidor']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'problem','Problema de Mercado','Pet shops independentes ainda dependem de canais informais e baixa estrutura digital.','Grande parte dos pet shops independentes enfrenta ausência de e-commerce, custos elevados para desenvolver tecnologia própria, dependência de atendimento manual, dificuldade de fidelização, baixa eficiência operacional e presença digital limitada. Como consequência, perdem competitividade para grandes redes e marketplaces consolidados.',2,NULL,'problema',ARRAY['problema','mercado','petshops']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'solution','Solução ClickPet','Plataforma completa para transformar qualquer pet shop em uma operação digital.','A solução contempla aplicativo para consumidores, painel administrativo para lojistas, gestão de pedidos, catálogo digital, marketplace regional, integração entre consumidores e estabelecimentos e tecnologia pronta para operação.',3,NULL,'solucao',ARRAY['solucao','produto','plataforma']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'market','Mercado em expansão','O setor pet cresce, mas a experiência ainda é analógica e fragmentada.','O Pitch Deck apresenta o mercado pet como um setor em expansão, pronto para inovação digital, com alta demanda e baixa digitalização. O material destaca 3º maior mercado de petshop do mundo, 10% de crescimento ao ano, R$ 78 bilhões de faturamento anual e 160 milhões de pets no país.',4,'p.5','crescimento_do_mercado',ARRAY['mercado','crescimento','dados']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'competition','Panorama competitivo','A ClickPet atua nas três frentes concorrenciais simultaneamente.','A análise de concorrência divide o mercado em delivery generalista, e-commerce nacional pet e plataforma especializada pet. A ClickPet é posicionada como a única plataforma que combina gestão completa do pet shop, delivery, serviços agendados e marketplace dedicado.',5,'p.3','tres_frentes_concorrencia',ARRAY['concorrencia','posicionamento','benchmark']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'product','Produto e operação','O produto combina experiência de compra, dashboard, pedidos, atendimento, promoções, logística e parametrização do negócio.','A apresentação do projeto descreve a plataforma digital como integração de produtos e serviços para pets com entrega sob demanda. O material detalha módulos de filtragem de produtos, tela de produto, dashboard do parceiro, gestão de pedidos, agenda de atendimento, cupons, entregadores, licenciamento e configurações operacionais.',6,NULL,'produto',ARRAY['produto','dashboard','modulos']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'funding','Rodada Pré-Seed','Rodada proposta de R$ 500 mil com valuation pré-money de R$ 3,2 milhões.','A rodada proposta é Pré-Seed, com valuation pré-money de R$ 3.200.000, captação pretendida de R$ 500.000, valuation pós-money de R$ 3.700.000 e participação ofertada de 13,5%.',7,NULL,'rodada',ARRAY['rodada','valuation','captação']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'vision','Visão de longo prazo','Construir a principal infraestrutura digital para pet shops independentes no Brasil.','A missão de longo prazo é consolidar um ecossistema que conecte consumidores, estabelecimentos e tecnologia em uma plataforma única, ampliando a competitividade das lojas parceiras e acompanhando a evolução do mercado pet brasileiro.',8,NULL,'visao_longo_prazo',ARRAY['visao','estrategia','longo-prazo']);
INSERT INTO investment_theses (company_id, source_id, title, thesis_summary, thesis_detail, market_reason, product_reason, traction_reason, timing_reason, investor_takeaway, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Digitalização vertical do pet shop independente','A ClickPet captura uma lacuna entre um mercado pet grande, recorrente e pulverizado e a baixa maturidade digital dos pet shops independentes.','A tese combina mercado recorrente, dor clara, produto já desenvolvido, baixo custo de entrada para lojistas e potencial de escala regional e nacional. A plataforma atua como infraestrutura digital para pequenos e médios pet shops, não como substituta desses lojistas.','O mercado pet brasileiro possui grande volume, recorrência de compra e forte presença de pequenos e médios estabelecimentos ainda pouco digitalizados.','O produto já contempla aplicativo, painel administrativo, catálogo, pedidos, serviços, promoções, logística, licenciamento e parametrização operacional.','MVP concluído, aplicativo publicado, plataforma operacional, website em funcionamento e primeiros estabelecimentos usando a solução.','O momento é favorável porque consumidores buscam conveniência e negócios locais precisam competir digitalmente com redes maiores e marketplaces.','A oportunidade está em financiar aquisição comercial e expansão de uma plataforma cujo risco tecnológico inicial já foi reduzido.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Unificação de uma jornada fragmentada','A vantagem competitiva vem da integração de compra, serviço, agenda, entrega e gestão em uma única plataforma especializada.','Apps generalistas não são especializados no setor pet; grandes redes focam em venda própria; marketplaces pet não resolvem completamente agenda, logística e operação local. A ClickPet propõe uma camada vertical completa.','O setor possui demanda, mas a experiência de cliente ainda é distribuída entre WhatsApp, redes sociais, sites, apps generalistas e atendimento manual.','A plataforma foi desenhada para centralizar a jornada do consumidor e a operação do lojista.','A existência de um produto funcional permite validação comercial com menor risco de construção.', 'A digitalização vertical ainda está em estágio inicial nos nichos de serviço pet.', 'Para investidores, a defesa está na especialização vertical e na posição de parceiro dos pet shops locais.',2);
