((SELECT id FROM investment_rounds WHERE company_id='11111111-1111-1111-1111-111111111111' AND round_name='Pré-Seed'),'Expansão comercial',20.00,100000.00,'Prospecção ativa, parcerias, operação comercial e expansão para novas regiões.','Validar modelo comercial e aumentar base de parceiros.',3),
