INSERT INTO market_opportunities (company_id, source_id, title, market_context, opportunity_summary, target_segment, timing_factor, scalability_factor, investor_relevance, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Mercado pet brasileiro pulverizado','Material de análise aponta R$ 78 bilhões em faturamento em 2025, 168 milhões de animais estimados, 48,7% de market share em PME pet shops e crescimento previsto de 9,6% para 2026.','A oportunidade-chave é atuar nos pequenos e médios pet shops locais, que representam parte relevante do mercado e ainda não possuem plataforma especializada de gestão e delivery integrados.','Pequenos e médios pet shops independentes e negócios locais do setor pet.','Consumidores tratam pets como membros da família e buscam conveniência, enquanto a experiência digital ainda é fragmentada.','Modelo com potencial de expansão regional por parceiros locais, marketplace e padronização de operação digital.', 'Mostra que a ClickPet endereça um segmento grande, recorrente e ainda pouco servido por soluções verticais completas.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Digitalização acessível para negócios independentes','Grandes redes já possuem presença digital, mas milhares de pequenos e médios pet shops dependem de canais informais.','A ClickPet reduz a barreira tecnológica ao oferecer uma solução pronta para operação, sem exigir que cada lojista desenvolva sistemas próprios.','Pet shops independentes com baixa maturidade digital.','A digitalização do consumo e a busca por conveniência aumentam a pressão competitiva sobre lojas locais.','A solução pode ser replicada em novas regiões mantendo foco vertical no setor pet.', 'A tese depende de transformar uma dor operacional real em receita transacional e recorrente.',2);
INSERT INTO market_problems (company_id, source_id, title, problem_summary, problem_detail, affected_audience, severity_level, business_impact, evidence_notes, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Tempo perdido e canais múltiplos','Donos de pets precisam resolver uma única necessidade em múltiplos canais.','A experiência atual exige alternar entre lojas, WhatsApp, redes sociais, sites, ligações e atendimento manual para compra, agendamento e acompanhamento.', 'Consumidores finais e pet shops que precisam atender manualmente.', 'medium','Reduz conversão, aumenta esforço do cliente e dificulta recorrência.', 'Pitch Deck: problema de tempo perdido e experiência fragmentada.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Ausência de e-commerce estruturado','Muitos pet shops independentes não possuem estrutura própria de venda online.','A falta de e-commerce limita alcance, controle de catálogo, disponibilidade de produtos e capacidade de competir com redes maiores.', 'Pet shops independentes.', 'high','Perda de competitividade e dependência de vendas manuais.', 'Investment Memo: ausência de estrutura de e-commerce.',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Dependência de WhatsApp e Instagram','Vendas e atendimento ainda ocorrem por canais informais e pouco escaláveis.','A dependência desses canais gera atendimento manual, baixa padronização, baixa visibilidade de dados e pouca automação.', 'Lojistas e consumidores.', 'high','Dificulta escala, métricas, fidelização e previsibilidade operacional.', 'Investment Memo e análise concorrencial destacam dependência de WhatsApp e processos manuais.',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Falta de transparência','Consumidores têm dificuldade em comparar preços, disponibilidade e qualidade.','A ausência de um ambiente centralizado limita comparação entre produtos, serviços, avaliações e disponibilidade real.', 'Consumidores finais.', 'medium','Gera incerteza na decisão de compra e reduz confiança.', 'Pitch Deck: falta de transparência em preços, disponibilidade e qualidade.',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Baixa eficiência operacional','Processos manuais reduzem produtividade e dificultam acompanhamento de pedidos, serviços e entregas.','Sem painel operacional, lojistas têm dificuldade para gerir pedidos, agenda, catálogo, promoções, entregadores, métricas e regras de entrega.', 'Pet shops, clínicas e serviços pet.', 'high','Eleva erro operacional, tempo de resposta e custo de gestão.', 'Investment Memo e Apresentação de Projeto.',5);
INSERT INTO solutions (company_id, source_id, title, solution_summary, solution_detail, delivered_value, implementation_status, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Tudo em um único lugar','Produtos, serviços e atendimentos integrados em uma jornada única.','A ClickPet centraliza lojas, produtos, serviços, agendamentos e comparação de preços, reduzindo a fragmentação da experiência.', 'Conveniência para consumidores e padronização para lojistas.', 'mvp_completed',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Plataforma pronta para operação','Infraestrutura completa para vendas online, gestão de pedidos e conexão com consumidores.','Inclui aplicativo, painel administrativo, catálogo digital, marketplace regional, gestão de pedidos e integração entre consumidores e estabelecimentos.', 'Reduz custo e tempo de digitalização para pet shops independentes.', 'operational_platform',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Transparente e confiável','Comparação clara e avaliações reais entre produtos, lojas e serviços.','A plataforma busca permitir escolha melhor informada pelo usuário, aumentando confiança e qualidade percebida.', 'Aumenta confiança, conversão e retenção.', 'presented_in_product',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Gestão operacional para parceiros','Dashboard operacional para vendas, pedidos, produtos, agenda, promoções, entregadores e parametrização.','O painel do parceiro concentra métricas em tempo real, gestão de catálogo, controle de pedidos, agenda de atendimento, cupons, logística e configurações de operação.', 'Melhora eficiência, reduz erros e aumenta retenção do lojista.', 'presented_in_product',4);
INSERT INTO product_modules (company_id, source_id, module_name, module_slug, module_summary, module_detail, user_group, business_value, status, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Aplicativo do consumidor','app-consumidor','Experiência de compra e descoberta para consumidores finais.','Permite encontrar produtos e serviços pet, filtrar catálogo, visualizar detalhes, avaliações, preço, quantidade e produtos relacionados.', 'Consumidor final','Aumenta conversão e recorrência de compra.', 'operational_or_presented',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Dashboard do parceiro','dashboard-parceiro','Painel administrativo para centralizar vendas, pedidos e gestão de produtos.','Oferece controle simples e visão consolidada do negócio, com métricas em tempo real, catálogo, preços e insights visuais.', 'Pet shop parceiro','Melhora eficiência e retenção da plataforma.', 'operational_or_presented',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Gestão de pedidos','gestao-pedidos','Controle completo de pedidos com status, histórico e ciclo de entrega.','Centraliza informações de pagamento, cliente, valor, status e volume para suporte à tomada de decisão.', 'Pet shop parceiro','Reduz erros e melhora tempo de resposta.', 'operational_or_presented',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Gestão de fluxo de atendimento','gestao-atendimento','Painel para controle de horários e serviços agendados.','Permite visualizar ocupação da agenda, status de compromissos e volume de agendamentos realizados versus concluídos.', 'Pet shop, clínica e serviço pet','Aumenta pontualidade, experiência do cliente e retenção.', 'operational_or_presented',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Gestão de promoções','gestao-promocoes','Criação e controle de campanhas de desconto e cupons.','Permite configurar cupons de primeira compra, influenciadores, datas sazonais, validade, limite de uso e valor mínimo.', 'Pet shop parceiro','Aumenta aquisição, conversão e performance de campanhas.', 'operational_or_presented',5),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Gestão logística','gestao-logistica','Cadastro e controle de parceiros de entrega.','Permite registrar entregadores, CNH, veículos, dados cadastrais e contatos para demanda de leva e traz.', 'Pet shop parceiro e entregadores','Apoia confiabilidade, organização e segurança operacional.', 'operational_or_presented',6),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Licenciamento e sustentabilidade','licenciamento-sustentabilidade','Controle do vínculo entre pet shop e plataforma ClickPet.','Dá visibilidade sobre custo fixo de software, continuidade operacional, cota de produtos e serviços, renovação automática e upgrades.', 'Pet shop parceiro','Apoia receita recorrente e expansão de planos.', 'operational_or_presented',7),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Parametrização operacional','parametrizacao-operacional','Configuração de regras fundamentais da operação.','Permite configurar contato, localização, políticas de frete, valor mínimo de pedido, horários semanais, raio de entrega e meios de pagamento.', 'Pet shop parceiro','Viabiliza operação local com regras próprias.', 'operational_or_presented',8);
INSERT INTO product_features (company_id, module_id, source_id, feature_name, feature_slug, feature_summary, feature_detail, user_benefit, investor_relevance, status, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='app-consumidor'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Filtragem de produtos','filtragem-produtos','Busca inteligente por espécie, raça, faixa de preço e categorias.','Sistema de filtragem desenvolvido para otimizar a busca do usuário e facilitar escolha do produto adequado.', 'Menos tempo procurando e mais precisão na compra.', 'Melhora experiência e taxa de conversão.', 'presented',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='app-consumidor'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Tela de produto otimizada','tela-produto-otimizada','Página com informações claras, variações, avaliações e CTA direto.','Estrutura com preço, quantidade, prova social e produtos relacionados para incentivar upsell e cross-sell.', 'Decisão rápida com menor fricção.', 'Aumenta conversão e ticket médio.', 'presented',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='dashboard-parceiro'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Métricas em tempo real','metricas-tempo-real','Indicadores de vendas, pedidos e produtos no dashboard.','Permite visão consolidada e tomada de decisão baseada em dados.', 'Gestão mais prática e objetiva.', 'Aumenta valor percebido pelo lojista e retenção.', 'presented',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='gestao-pedidos'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Segmentação por status de pedido','segmentacao-status-pedido','Organização dos pedidos por status para priorização.','Ajuda a controlar ciclo de entrega, pagamento, cliente, valor e histórico.', 'Reduz atrasos e melhora previsibilidade.', 'Aumenta eficiência operacional.', 'presented',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='gestao-atendimento'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Agenda por ciclo de vida','agenda-ciclo-vida','Status Pendente, Confirmado, Concluído ou Cancelado.','Permite medir comparecimento, volume de agendamentos e desempenho mensal.', 'Melhor organização do atendimento.', 'Expande a plataforma para serviços, não apenas produtos.', 'presented',5),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='gestao-promocoes'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Cupons e campanhas','cupons-campanhas','Configuração de gatilhos, prazos, limites de uso e regras de ativação.','Inclui cupons de primeira compra, parcerias com influenciadores e datas sazonais.', 'Mais controle sobre ações promocionais.', 'Apoia aquisição e geração de demanda.', 'presented',6),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='gestao-logistica'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Cadastro de entregadores','cadastro-entregadores','Registro de dados de entregadores, CNH e veículos.','Centraliza dados cadastrais, frota, contatos e manutenção da base logística.', 'Mais segurança e organização na entrega.', 'Fortalece logística local e confiabilidade da operação.', 'presented',7),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM product_modules WHERE module_slug='parametrizacao-operacional'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'Regras de frete e raio de entrega','regras-frete-raio-entrega','Configuração de alcance, taxa, horários e valor mínimo.','Permite adaptar a operação à realidade de cada pet shop e região.', 'Operação mais personalizada e previsível.', 'Facilita escala regional mantendo flexibilidade local.', 'presented',8);
