('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Parcerias estratégicas','Construção de canais de expansão por parceiros locais e setoriais.','Parcerias podem ampliar entrada em novas regiões, serviços e ecossistema pet.', 'parcerias','Reduzir custo de aquisição e ampliar capilaridade.', 'Expansão regional mais eficiente.',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Marketing digital','Campanhas para atrair lojistas e consumidores.','Uso de canais digitais para aquisição, awareness, educação de mercado e geração de demanda.', 'marketing digital','Fortalecer canais de aquisição.', 'Aumento de cadastros e reconhecimento da marca.',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Programa de indicação','Estimular indicação entre lojistas, consumidores e parceiros.','Modelo de crescimento baseado em rede local e recomendação.', 'referral','Reduzir CAC e acelerar aquisição.', 'Crescimento orgânico e validação de confiança.',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Ações regionais de expansão','Entrada planejada em novas regiões com foco local.','Expansão por regiões prioritárias, combinando prospecção, parceiros, marketing e onboarding.', 'regional','Validar replicabilidade do modelo.', 'Escala geográfica progressiva.',5);
