VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'iFood','ifood','delivery_app','Plataforma de delivery generalista que atende pet shops como mais uma categoria, sem gestão dedicada ao setor pet.','Líder em delivery generalista no Brasil.'),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Aiqfome','aiqfome','delivery_app','Plataforma generalista do Grupo Magalu com presença no interior do Brasil.','Delivery generalista regional.'),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Grupo Petz-Cobasi','grupo-petz-cobasi','retail_chain','Grande rede varejista pet com presença física e digital, focada principalmente em venda de produtos próprios.','Grande rede varejista nacional.'),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Petlove','petlove','marketplace','Marketplace pet e e-commerce nacional, com foco em produtos e modelo whitelabel, mas lacunas em serviços agendados, logística e gestão operacional completa para pequenos negócios.','E-commerce/marketplace pet nacional.'),
