INSERT INTO competitor_analysis (company_id, competitor_id, source_id, comparison_dimension, competitor_strength, competitor_weakness, clickpet_advantage, threat_level, opportunity_for_clickpet, strategic_note, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM competitors WHERE slug='ifood'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Delivery generalista','Grande base de clientes, parceiros cadastrados, infraestrutura de delivery e marca forte.','Comissão elevada, pet shop é apenas mais uma categoria, sem gestão de agenda, banho, tosa, serviços ou catálogo especializado.','Plataforma 100% dedicada ao ecossistema pet, com dashboard completo, agenda, status, métricas e gestão de parceiros de entrega.', 'medium','Capturar lojistas que precisam de operação pet vertical, não apenas entrega.', 'Material cita comissão iFood de 12% a 31% e comissão média de 28,7%.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM competitors WHERE slug='aiqfome'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Delivery regional generalista','Presença em cidades do interior e operação ligada ao Grupo Magalu.','Não oferece gestão especializada de pet shop, serviços, agenda e logística pet dedicada.','Modelo especializado com foco em produtos, serviços, agenda e relacionamento do pet shop.', 'medium','Entrar em regiões onde apps generalistas atendem demanda sem resolver operação do lojista.', 'Aiqfome é tratado como concorrente indireto generalista.',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM competitors WHERE slug='grupo-petz-cobasi'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Grande rede varejista','Marca forte, lojas físicas, e-commerce e escala nacional.','Foco em produto e lojas próprias; não habilita pet shops independentes com logística integrada e não alcança o mercado fragmentado de pequenos negócios locais.','A ClickPet atua como infraestrutura para pet shops independentes e pode digitalizar o segmento oposto ao das megastores.', 'high','Fortalecer lojas locais contra redes nacionais por meio de tecnologia acessível.', 'Material cita R$ 7,9 bi de faturamento 2025, 500+ lojas físicas, ~11% de market share e 140+ cidades atendidas.',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM competitors WHERE slug='petlove'),(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Marketplace pet','Marca nacional, marketplace e presença digital no setor pet.','Foco em produto, não em serviços agendados como banho, tosa e leva e traz; whitelabel básico sem gestão de agenda, pedidos, logística ou entregadores; exige CNPJ ativo e exclui parte de pequenos negócios.','A ClickPet entrega produto, serviço, agenda e logística em uma plataforma vertical completa.', 'high','Atender lacunas operacionais dos pequenos pet shops e serviços locais.', 'Material cita R$ 2,45 bi de receita projetada 2025, +38% crescimento esperado, 4 mil+ petshops parceiros whitelabel e 89 mil pets com seguro de saúde.',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM competitors WHERE slug='petshops-locais'),(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Operação local informal','Proximidade local, relacionamento com clientes e conhecimento da região.','Baixa integração, baixa experiência digital, pouca transparência, dependência de WhatsApp e processos manuais.','A ClickPet transforma esses estabelecimentos em operações digitais sem competir diretamente com eles.', 'low','Converter concorrência fragmentada em base parceira da plataforma.', 'Pet shops locais são principalmente público-alvo e oferta da plataforma, não ameaça direta.',5);
INSERT INTO competitive_advantages (company_id, source_id, advantage_name, advantage_summary, advantage_detail, defensibility_level, investor_relevance, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Foco em pequenos e médios pet shops','A ClickPet é desenhada para o segmento independente pouco digitalizado.','Grandes redes vendem para o consumidor final; a ClickPet fornece infraestrutura para pet shops independentes competirem digitalmente.', 'medium','Cria posicionamento claro e reduz conflito com lojistas.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Plataforma pronta para operação','Baixo custo de entrada para lojistas.','Pet shops não precisam desenvolver tecnologia própria para vender online, gerir pedidos e se conectar com consumidores.', 'medium','Acelera adoção e reduz barreiras comerciais.',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'Integração absoluta da jornada','Compra, serviço, entrega e experiência em uma jornada fluida.','O Pitch Deck posiciona a ClickPet como camada de inteligência que unifica compra, serviço, entrega e experiência para o bem-estar animal.', 'high','Diferencia a plataforma de apps generalistas, marketplaces e lojas isoladas.',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Marketplace especializado','Ambiente dedicado ao ecossistema pet.','A especialização permite linguagem, funcionalidades e operação voltadas para comportamento e necessidades do setor pet.', 'medium','Aumenta relevância para lojistas e consumidores do nicho.',4),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Arquitetura preparada para expansão nacional','Modelo pode ser replicado em novas regiões.','A combinação de plataforma, parceiros locais e marketplace regional permite expansão progressiva para outros mercados.', 'medium','Sustenta tese de escala e retorno de venture capital.',5);
INSERT INTO risks (company_id, source_id, risk_name, risk_summary, risk_detail, risk_level, mitigation_strategy, investor_note, display_order)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Velocidade de aquisição de clientes','Risco de crescimento comercial mais lento que o previsto.','A empresa precisa adquirir pet shops cadastrados e ativos para validar o modelo e iniciar geração de receita recorrente.', 'high','Uso da rodada para marketing, aquisição, expansão comercial, prospecção ativa e parcerias estratégicas.', 'Principal risco da etapa Pré-Seed está na execução comercial.',1),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Adoção pelos estabelecimentos','Pet shops podem ter resistência operacional ou baixa maturidade digital.','A adoção depende de onboarding simples, valor percebido rápido e suporte à mudança de processos manuais.', 'medium','Plataforma pronta para operação, baixo custo de entrada e foco em resolver dores operacionais do lojista.', 'Risco típico de transformação digital em PME.',2),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Necessidade de capital para expansão','Escala comercial e evolução de produto exigem capital.','Marketing, tecnologia, equipe comercial e expansão regional dependem de investimento externo.', 'medium','Captação proposta de R$ 500.000 com alocação clara por área.', 'Rodada busca financiar validação e crescimento inicial.',3),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Aumento da concorrência','Players maiores podem ampliar atuação no setor pet.','Apps generalistas, varejistas e marketplaces podem investir em soluções específicas para o setor.', 'medium','Especialização vertical, relacionamento com pet shops independentes e execução rápida em nichos locais.', 'Defensibilidade dependerá de base de parceiros, dados, operação local e produto especializado.',4);
INSERT INTO investor_faqs (company_id, source_id, question, short_answer, detailed_answer, category, display_order, tags)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'O que é a ClickPet?','A ClickPet é uma plataforma B2B2C para digitalizar pet shops independentes.','Ela oferece aplicativo para consumidores, painel administrativo para lojistas, catálogo digital, marketplace regional, gestão de pedidos e integração entre consumidores e estabelecimentos pet.', 'company',1,ARRAY['empresa','resumo']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Qual problema a ClickPet resolve?','Resolve a baixa digitalização e fragmentação operacional dos pet shops independentes.','Muitos pet shops dependem de WhatsApp, Instagram, atendimento manual e baixa presença digital, perdendo competitividade para redes e marketplaces maiores.', 'problem',2,ARRAY['problema','mercado']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Como a ClickPet ganha dinheiro?','A principal receita prevista é comissão sobre vendas realizadas na plataforma.','No médio e longo prazo, a empresa também poderá monetizar por planos premium, publicidade interna, serviços financeiros, logística integrada e ferramentas de marketing para lojistas.', 'business_model',3,ARRAY['receita','modelo-de-negocio']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Qual é o estágio atual da empresa?','A empresa está em estágio Pré-Seed, com MVP concluído e plataforma operacional.','O memo informa MVP concluído, aplicativo publicado, website operacional, infraestrutura própria e primeiros pet shops utilizando a solução.', 'traction',4,ARRAY['tracao','status']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Qual é a rodada de investimento?','Rodada Pré-Seed de R$ 500.000 com valuation pré-money proposto de R$ 3.200.000.','A rodada propõe valuation pós-money de R$ 3.700.000 e participação ofertada de 13,5%.', 'funding',5,ARRAY['rodada','valuation']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Como os recursos serão usados?','40% produto e tecnologia, 30% marketing e aquisição, 20% expansão comercial e 10% capital de giro.','A distribuição busca fortalecer produto, acelerar aquisição, validar canais comerciais e dar sustentação operacional à fase de crescimento.', 'funding',6,ARRAY['uso-dos-recursos','captação']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Quais são os diferenciais competitivos?','Foco em pet shops independentes, plataforma pronta para operação, marketplace especializado e integração da jornada pet.','A ClickPet se posiciona como parceiro tecnológico dos lojistas, integrando consumidor, catálogo, pedidos, serviços, agenda, logística e gestão operacional.', 'competition',7,ARRAY['diferenciais','concorrencia']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Quais são os principais riscos?','Aquisição de clientes, adoção dos estabelecimentos, necessidade de capital e aumento da concorrência.','Esses riscos são parcialmente mitigados pelo produto já desenvolvido, MVP funcional, plataforma operacional, primeiros usuários e tendência de digitalização do setor pet.', 'risk',8,ARRAY['riscos']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='Investment Memo ClickPet'),'Qual é a visão de longo prazo?','Construir a principal infraestrutura digital para pet shops independentes no Brasil.','A visão é consolidar um ecossistema que conecte consumidores, estabelecimentos e tecnologia em uma plataforma única, ampliando a competitividade das lojas parceiras.', 'vision',9,ARRAY['visao','longo-prazo']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'Por que investir agora?','Porque o produto já existe, o mercado é grande e a digitalização de pet shops independentes ainda está em estágio inicial.','A rodada financia a transição de produto validado tecnicamente para validação comercial e expansão, em um mercado recorrente com lacuna clara entre consumidores digitais e lojistas locais pouco estruturados.', 'investment_thesis',10,ARRAY['tese','investimento']);
INSERT INTO knowledge_entries (company_id, source_id, category, title, answer_summary, answer_detail, investor_relevance, confidence_score, tags)
VALUES
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet PitchDeck'),'company','Origem da ClickPet','A ClickPet nasceu de uma dor real: compras e serviços pet fragmentados.','O Pitch Deck apresenta a origem da ClickPet em etapas: insight inicial sobre a dificuldade de donos de pets com compras e serviços fragmentados; validação por análise de mercado e comportamento do consumidor; estruturação da operação, parceiros e serviços; ideação do conceito; desenvolvimento do modelo de negócio e experiência do usuário; e momento ideal de lançamento com foco em escalabilidade.', 'Ajuda investidores a entenderem a evolução lógica da oportunidade, da dor ao produto.',0.95,ARRAY['origem','historia','pitch']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Análise de Concorrência'),'market','Oportunidade no mercado fragmentado','48,7% do mercado está nas mãos de pequenos e médios pet shops locais segundo o material de concorrência.','A análise aponta que esse segmento fatura aproximadamente R$ 37,5 bilhões ao ano sem uma plataforma especializada de gestão e delivery integrados, formando a oportunidade central para a ClickPet.', 'Dimensiona o segmento-alvo e sustenta a tese de mercado.',0.90,ARRAY['mercado','pme','oportunidade']),
('11111111-1111-1111-1111-111111111111',(SELECT id FROM institutional_sources WHERE title='ClickPet - Apresentação de Projeto'),'product','Produto como infraestrutura para lojistas','A ClickPet oferece ferramentas operacionais que vão além da vitrine digital.','A apresentação de projeto descreve dashboard de vendas, pedidos, produtos, agenda, cupons, entregadores, assinatura/licenciamento e parametrização de regras operacionais, mostrando que a proposta é infraestrutura de operação, não apenas uma página de produtos.', 'Evidencia profundidade de produto e potencial de retenção B2B.',0.95,ARRAY['produto','dashboard','lojistas']);
